use crate::*;
pub(super) const DOCUMENTATION:BuiltinDocumentation=BuiltinDocumentation{
 authority:BuiltinDocumentationAuthority::Catalog,title:Some("fminsearch"),slug:Some("fminsearch"),summary:"Minimize a real scalar objective with Nelder-Mead simplex search.",description:"x = fminsearch(fun,x0) performs derivative-free unconstrained search from a nonempty finite real double array. The objective receives x with the original shape; x retains that shape. No derivative, convexity or global-minimum guarantee is assumed.",keywords:&["fminsearch","Nelder-Mead","simplex","derivative-free","optimization"],related:&["optimset","fminunc","fminbnd","optimplotx","optimplotfunccount","optimplotfval"],
 sections:&[BuiltinDocumentationSection{heading:"Forms and controls",paragraphs:&[
 "Supported forms are fminsearch(fun,x0), fminsearch(fun,x0,options), and fminsearch(problem), where problem has objective, x0, solver='fminsearch', and optional options. fun is a function handle or function name. Up to four outputs are x, fval, exitflag, and output with iterations, funcCount, algorithm and message. Use optimset, not optimoptions('fminsearch').",
 "The eight legacy controls are Display, FunValCheck, MaxFunEvals, MaxIter, OutputFcn, PlotFcns, TolFun and TolX; case-insensitive unambiguous abbreviations are accepted. Empty numeric [] means the default. TolX and TolFun default to 1e-4 and must be positive; both absolute simplex spreads must pass to converge. Both budgets default to 200*numberOfVariables. MaxIter accepts a nonnegative integer-valued floating scalar; zero evaluates only the starting point, reports zero iterations and does not construct the remaining simplex. MaxFunEvals must be a positive integer-valued floating scalar. The literal dimension-dependent default from optimset('fminsearch') is decoded without evaluating arbitrary expressions. Unsupported nonempty options are rejected, not ignored.",
 "The initial simplex adds 5% to each nonzero coordinate and 0.00025 to zero coordinates. Reflection, expansion, outside/inside contraction and shrink use the general Nelder-Mead algorithm. Only completed simplex operations count as iterations; every actual objective call counts, including a partially initialized or shrunk simplex. Hard evaluation limits are never exceeded. Flag 1 means both finite simplex spreads pass, not a mathematical minimum certificate; 0 means a budget limit and -1 means an observer stop. The best actually evaluated point is returned on budget or requested stop.",
 "FunValCheck='on' rejects objective NaN. With 'off' (default), NaN ranks after ordinary values and cannot establish convergence. Inf is permitted in either setting but cannot establish finite simplex convergence. Objectives must return one real single or double value; complex, logical and typed-integer results are not admitted.",
 "OutputFcn accepts a handle or cell array of handles. PlotFcns accepts a handle, name, or cell array of handles/names. Each callback receives (x,optimValues,state), with iteration, funccount, fval and procedure, and states init, iter and done. Each must return a logical scalar stop flag. Init/iter stop requests are combined; a done return is validated but does not relabel completed termination. original errors and cancellation propagate without callback replay. Init follows the first evaluation; iter follows each complete simplex operation; done follows normal completion or stop. Plot callbacks use separate invocation-owned axes, selected before every callback; graphics support requires plot-core. The predefined optimplotx, optimplotfunccount and optimplotfval helpers are real graphics, not console stand-ins.",
 "Display defaults to notify (nonpositive termination only). final writes a terminal summary; iter writes an initial row and a row per complete simplex operation plus the summary; off/none are silent. Presentation uses the original invocation console/diary route and adds no objective calls. RunMat does not promise byte-identical MATLAB console layout."]},
 BuiltinDocumentationSection{heading:"Execution and supported boundary",paragraphs:&[
 "The solver uses host binary64 arithmetic. x0 must be real dense double; objective/control scalars may be real single or double. Original Automatic-residency numeric values may be gathered; explicit or unproven device intent is refused before provider transfer. There is no provider-native solver or typed-integer/logical overload. Callback captures remain rooted in their original invocation and are not recursively gathered as option metadata.",
 "Finite host-memory execution is currently unsupported: requests with a finite policy fail before derivative-free callbacks, metadata materialization or simplex/history/result allocation. Ordinary unbounded execution is unchanged. Cancellation and cooperative yielding are checked through long scans, sorting, simplex work and callback boundaries; no extra objective evaluation is used for reporting."]}],
 examples:&[BuiltinExample{id:"example-1",title:"Minimize the Rosenbrock function",program:"f = @(x) 100*(x(2)-x(1)^2)^2+(1-x(1))^2;\nopts = optimset('Display','off');\n[x,fval,flag,out] = fminsearch(f,[-1.2 1],opts)",display_output:None,compatibility:BuiltinExampleCompatibility::Matlab,harness:BuiltinExampleHarness::Portable,fixture:BuiltinExampleFixture::None,requirements:BuiltinExampleRequirements::NONE,verification:BuiltinExampleVerification::Assertions{source:"assert(norm(x-[1 1])<1e-3); assert(fval<1e-6); assert(flag==1); assert(out.funcCount>out.iterations);"}},
 BuiltinExample{id:"example-2",title:"Preserve a matrix-shaped search variable",program:"target = [1 2;3 4];\nf = @(x) sum(sum((x-target).^2));\nopts = optimset('TolX',1e-7,'TolFun',1e-10,'MaxFunEvals',4000,'MaxIter',2000,'Display','off');\nx = fminsearch(f,zeros(2),opts)",display_output:None,compatibility:BuiltinExampleCompatibility::Matlab,harness:BuiltinExampleHarness::Portable,fixture:BuiltinExampleFixture::None,requirements:BuiltinExampleRequirements::NONE,verification:BuiltinExampleVerification::Assertions{source:"assert(isequal(size(x),[2 2])); assert(norm(x-target)<1e-4);"}}],
example_exemption:None,
faqs:&[BuiltinDocumentationFaq{question:"Does simplex convergence prove a minimum?",answer:"No. Exitflag 1 reports finite TolX and TolFun simplex spreads; Nelder-Mead can stagnate and does not certify local or global optimality."},BuiltinDocumentationFaq{question:"Which option constructor should I use?",answer:"Use optimset. fminsearch is intentionally not an optimoptions solver identity."}],
links:&[BuiltinDocumentationLink{label:"MathWorks fminsearch",target:BuiltinDocumentationLinkTarget::External("https://www.mathworks.com/help/matlab/ref/fminsearch.html")},BuiltinDocumentationLink{label:"optimset",target:BuiltinDocumentationLinkTarget::Builtin("optimset")}],media:&[],
evidence:BuiltinDocumentationEvidence{implementation:&[BuiltinDocumentationLink{label:"Invocation-owned Nelder-Mead implementation",target:BuiltinDocumentationLinkTarget::Source("https://github.com/runmat-org/runmat/blob/main/crates/runmat-runtime/src/builtins/math/optim/fminsearch.rs")}],verification:&[BuiltinEvidenceReference{kind:BuiltinEvidenceKind::UnitTest,label:"General simplex, counts, shapes, observers, limits and original control owners",location:"builtins::math::optim::fminsearch::tests"}],notes:&["Source fixtures do not establish fresh CLI, Native, browser, provider or MATLAB execution acceptance."]},introduced:None,status:Some(BuiltinDocumentationStatus::Partial),};
